136	  var SHOP = container.dataset.shop;
137	  // app.url resolves to the App Proxy URL (e.g. https://store.myshopify.com/apps/zipcheck).
138	  // If for any reason it is empty (e.g. dev environment or Shopify Liquid context issue),
139	  // fall back to the relative proxy path so the request still routes correctly through
140	  // Shopify's App Proxy rather than hitting the store's own domain as a missing route.
141	  var _rawApi = (container.dataset.api || "").replace(/\/$/, "");
142	  var _proxyPath = (container.dataset.proxy || "/apps/zipcheck").replace(/\/$/, "");
143	  // Prefer app.url when it looks like a full URL; otherwise use the relative proxy path
144	  // (which Shopify will forward to our app via the App Proxy config).
145	  var API_BASE = (_rawApi && _rawApi.indexOf("http") === 0) ? _rawApi : _proxyPath;
146	
147	  // ── Pre-lock: applied synchronously BEFORE the async config fetch ────────────
148	  // This eliminates the race window where ATC/Buy Now buttons are clickable
149	  // while the config fetch is in flight (typically 100–500 ms).
150	  // renderWidget() will call _zccUnlock() immediately if the feature is
151	  // disabled (lockButtonsUntilZipCheck:false) or position is "inline".
152	  var _zccLockStyleId = 'zcc-lock-style';
153	  function _zccInjectLockCss() {
154	    if (document.getElementById(_zccLockStyleId)) return;
155	    var s = document.createElement('style');
156	    s.id = _zccLockStyleId;
157	    s.textContent =
158	      'html[data-zcc-locked] form[action*="/cart/add"] button[type="submit"],' +
159	      'html[data-zcc-locked] button[name="add"],' +
160	      'html[data-zcc-locked] .product-form__submit,' +
161	      'html[data-zcc-locked] [data-product-add],' +
162	      'html[data-zcc-locked] .btn--add-to-cart,' +
163	      'html[data-zcc-locked] .product-form button[type="submit"],' +
164	      'html[data-zcc-locked] button.product-form__cart-submit,' +
165	      'html[data-zcc-locked] .product__submit button[type="submit"],' +
166	      'html[data-zcc-locked] .pdp-form button[type="submit"]' +
167	      '{opacity:.4!important;pointer-events:none!important;cursor:not-allowed!important;}' +
168	      'html[data-zcc-locked] .shopify-payment-button,' +
169	      'html[data-zcc-locked] [data-shopify="payment-button"],' +
170	      'html[data-zcc-locked] .shopify-payment-button__button--unbranded' +
171	      '{position:relative!important;opacity:.4!important;pointer-events:none!important;cursor:not-allowed!important;}' +
172	      'html[data-zcc-locked] .shopify-payment-button::after,' +
173	      'html[data-zcc-locked] [data-shopify="payment-button"]::after' +
174	      '{content:""!important;position:absolute!important;inset:0!important;z-index:2147483647!important;cursor:not-allowed!important;background:transparent!important;}';
175	    (document.head || document.documentElement).appendChild(s);
