283	  // ── Block ATC buttons on page load (before any ZIP check) ─────────────────
284	  function blockCartButtonsInitial() {
285	    var ATC_SELECTORS = [
286	      'button[name="add"]',
287	      '.product-form__submit',
288	      '[data-product-add]',
289	      '.btn--add-to-cart',
290	      '.product-form button[type="submit"]',
291	      'button.shopify-payment-button__button',
292	      '.shopify-payment-button button',
293	      'button.product-form__cart-submit'
294	    ].join(',');
295	
296	    function doBlock() {
297	      try {
298	        var atcBtns = document.querySelectorAll(ATC_SELECTORS);
299	        atcBtns.forEach(function(b) {
300	          if (!b.closest('[data-zcc-widget]')) {
301	            if (!b.getAttribute('data-zcc-blocked')) {
302	              b.setAttribute('data-zcc-orig-title', b.title || '');
303	            }
304	            b.disabled = true;
305	            b.style.opacity = '0.5';
306	            b.title = 'Please check ZIP code availability first';
307	            b.setAttribute('data-zcc-blocked', 'true');
308	          }
309	        });
310	      } catch(e) {}
311	    }
312	
313	    // Block immediately + delays for dynamic buttons (Shopify Buy Now renders late)
314	    doBlock();
315	    setTimeout(doBlock, 500);
316	    setTimeout(doBlock, 1500);
317	
318	    // MutationObserver for dynamic payment buttons
319	    if (typeof MutationObserver !== 'undefined') {
320	      var observer = new MutationObserver(function() { doBlock(); });
321	      var form = document.querySelector('.product-form, [data-product-form], form[action*="/cart/add"]');
322	      if (form) {
