357	  // ── Scope custom CSS: auto-prefix selectors with widget container ID ──────
358	  function scopeCustomCss(rawCss, wid) {
359	    if (!rawCss) return "";
360	    // Defense-in-depth: sanitize the same vectors as the API-side sanitizeCss().
361	    // The API already strips these before serving, but if a future code path
362	    // (e.g. metafield fallback) bypasses the API, this layer still protects.
363	    var css = rawCss
364	      .replace(/<style\b[^>]*>/gi, "")
365	      .replace(/<\/style>/gi, "")
366	      .replace(/@import\b[^;]*(;|$)/gi, "")
367	      .replace(/\bexpression\s*\(/gi, "")
368	      .replace(/url\s*\(\s*['"]?\s*javascript\s*:/gi, "url(")
369	      .replace(/url\s*\(\s*['"]?\s*data\s*:/gi, "url(");
370	    var result = "";
371	    var i = 0;
372	    while (i < css.length) {
373	      // Skip whitespace
374	      while (i < css.length && /\s/.test(css[i])) { result += css[i]; i++; }
375	      if (i >= css.length) break;
376	      // Pass through @keyframes and @font-face unchanged
377	      if (css[i] === '@') {
378	        var atRule = "";
379	        var j = i;
380	        while (j < css.length && css[j] !== '{' && css[j] !== ';') { atRule += css[j]; j++; }
381	        var atName = atRule.trim().toLowerCase();
382	        if (atName.indexOf("@keyframes") === 0 || atName.indexOf("@font-face") === 0) {
383	          result += atRule;
384	          if (j < css.length && css[j] === '{') {
385	            var depth = 1; result += css[j]; j++;
386	            while (j < css.length && depth > 0) {
387	              if (css[j] === '{') depth++;
388	              if (css[j] === '}') depth--;
389	              result += css[j]; j++;
390	            }
391	          }
392	          i = j; continue;
393	        }
394	        // @media: scope inner rules
395	        if (atName.indexOf("@media") === 0) {
396	          result += atRule;
397	          if (j < css.length && css[j] === '{') {
398	            result += '{'; j++;
399	            // Collect inner content
400	            var depth = 1; var inner = "";
401	            while (j < css.length && depth > 0) {
402	              if (css[j] === '{') depth++;
403	              if (css[j] === '}') depth--;
404	              if (depth > 0) inner += css[j];
405	              j++;
406	            }
407	            result += scopeCustomCss(inner, wid);
408	            result += '}';
409	          }
410	          i = j; continue;
411	        }
412	      }
413	      // Regular rule: grab selector, prefix with #wid
414	      var sel = ""; var body = "";
415	      while (i < css.length && css[i] !== '{') { sel += css[i]; i++; }
416	      if (i < css.length) { i++; } // skip {
417	      var depth = 1;
418	      while (i < css.length && depth > 0) {
419	        if (css[i] === '{') depth++;
420	        if (css[i] === '}') depth--;
421	        if (depth > 0) body += css[i];
422	        i++;
423	      }
424	      if (sel.trim()) {
425	        // Split multiple selectors by comma and prefix each
426	        var selectors = sel.split(',').map(function(s) {
427	          s = s.trim();
428	          if (!s) return '';
429	          return '#' + wid + ' ' + s;
430	        }).filter(Boolean).join(', ');
431	        result += selectors + ' {' + body + '}';
432	      }
433	    }
434	    return result;
435	  }
